import json
import sys

import click

from weather_cli.api import WeatherAPIError, fetch_forecast, fetch_weather
from weather_cli.display import render_forecast, render_weather


def _get_api_key(ctx: click.Context) -> str:
    api_key = ctx.obj["api_key"]
    if not api_key:
        click.echo("Error: Missing API key. Pass --api-key or set OPENWEATHER_API_KEY.", err=True)
        sys.exit(1)
    return api_key


class DefaultGroup(click.Group):
    """A click group that falls back to a default command when no subcommand is matched."""

    def __init__(self, *args, default_cmd: str = "current", **kwargs):
        super().__init__(*args, **kwargs)
        self.default_cmd = default_cmd

    def parse_args(self, ctx, args):
        if args and args[0] not in self.commands and not args[0].startswith("-"):
            args = [self.default_cmd, *args]
        return super().parse_args(ctx, args)


@click.group(cls=DefaultGroup)
@click.option(
    "--api-key",
    envvar="OPENWEATHER_API_KEY",
    help="OpenWeatherMap API key (or set OPENWEATHER_API_KEY).",
)
@click.option(
    "--units",
    type=click.Choice(["metric", "imperial", "standard"], case_sensitive=False),
    default="metric",
    help="Unit system for temperature and wind speed.",
)
@click.option(
    "--json-output", "use_json",
    is_flag=True,
    default=False,
    help="Output raw JSON instead of formatted tables.",
)
@click.pass_context
def main(ctx: click.Context, api_key: str | None, units: str, use_json: bool) -> None:
    """A CLI tool to fetch weather data by city name.

    You can omit the subcommand for current weather: weather London
    """
    ctx.ensure_object(dict)
    ctx.obj["api_key"] = api_key
    ctx.obj["units"] = units
    ctx.obj["use_json"] = use_json


@main.command()
@click.argument("city")
@click.option("--verbose", "-v", is_flag=True, default=False, help="Show extra details (pressure, visibility, sunrise/sunset).")
@click.pass_context
def current(ctx: click.Context, city: str, verbose: bool) -> None:
    """Show current weather for CITY."""
    api_key = _get_api_key(ctx)
    units = ctx.obj["units"]

    try:
        data = fetch_weather(city, api_key, units)
    except WeatherAPIError as exc:
        click.echo(f"Error: {exc}", err=True)
        sys.exit(1)

    if ctx.obj["use_json"]:
        click.echo(json.dumps(data, indent=2))
    else:
        render_weather(data, units, verbose=verbose)


@main.command()
@click.argument("city")
@click.option("--days", default=5, type=click.IntRange(1, 5), help="Number of days to show (1-5).")
@click.pass_context
def forecast(ctx: click.Context, city: str, days: int) -> None:
    """Show multi-day forecast for CITY."""
    api_key = _get_api_key(ctx)
    units = ctx.obj["units"]

    try:
        data = fetch_forecast(city, api_key, units)
    except WeatherAPIError as exc:
        click.echo(f"Error: {exc}", err=True)
        sys.exit(1)

    if ctx.obj["use_json"]:
        click.echo(json.dumps(data, indent=2))
    else:
        render_forecast(data, units, days)

